sect1.para:
  यसको अर्थ तलका दुई लाइनहरू तार्किक रूपमा समान (logically equivalent) छन्।

   |> को प्रयोग


<?php
$result = "Hello World" |> strlen(...);
echo $result, PHP_EOL;

$result = strlen("Hello World");
echo $result, PHP_EOL;
?>


   &example.outputs;


11
11

एउटा मात्र call का लागि यो खासै उपयोगी हुँदैन। जब धेरै calls लाई एकसाथ chain गरिन्छ, तब यो उपयोगी बन्छ। अर्थात्, तलका दुई code fragments तार्किक रूपमा समान छन्:
|> calls लाई Chain गर्ने
<?php $result = "PHP Rocks" |> htmlentities(...) |> str_split(...) |> (fn($x) => array_map(strtoupper(...), $x)) |> (fn($x) => array_filter($x, fn($v) => $v != 'O')) ; print_r($result);
$temp = "PHP Rocks"; $temp = htmlentities($temp); $temp = str_split($temp); $temp = array_map(strtoupper(...), $temp); $temp = array_filter($temp, fn($v) => $v != 'O'); $result = $temp; print_r($result); ?>
&example.outputs;
Array ( [0] => P [1] => H [2] => P [3] => [4] => R [6] => C [7] => K [8] => S ) Array ( [0] => P [1] => H [2] => P [3] => [4] => R [6] => C [7] => K [8] => S )
